select id, shipped_date, status, avg(cost) over (partition by order_id order by shipped_date asc, id asc rows between unbounded preceding and current row) as running_avg_cost, max(cost) over (partition by order_id order by shipped_date asc, id asc rows between unbounded preceding and current row) as running_max_cost, min(cost) over (partition by order_id order by shipped_date asc, id asc rows between unbounded preceding and current row) as running_min_cost, row_number() over (partition by status, order_id order by shipped_date desc, id asc) as seq_no from shipments
